import{_ as n,o as i,c as d,a3 as h}from"./chunks/framework.D8u9WiMi.js";const t="/SumUP/assets/cable-external-rotation.BmX_7uC4.gif",a="/SumUP/assets/band-reverse-fly.C8w0efSE.gif",g="/SumUP/assets/band-assisted-pull-up.lh8uFQc_.gif",c="/SumUP/assets/lat-pulldown.CDrdLor_.gif",l="/SumUP/assets/cable-rope-seated-row.B_GeOqyH.gif",b="/SumUP/assets/dumbbell-bent-over-row.D5nL9xXg.gif",s="/SumUP/assets/dumbbell-reverse-fly.DV9suBxu.gif",p="/SumUP/assets/cable-straight-arm-pulldown.C9n1DBFC.gif",u="/SumUP/assets/dumbbell-biceps-curl.CLK3PsTG.gif",m="/SumUP/assets/cable-curl.DmTXyCzD.gif",o="/SumUP/assets/kneeling-lat-stretch.Dyc3m-WQ.gif",q="/SumUP/assets/upper-back-stretch.ByXtgl1l.gif",P="/SumUP/assets/back-pec-stretch.Cb8RWBig.gif",e="/SumUP/assets/dynamic-chest-stretch.CioYToiY.gif",_="/SumUP/assets/lever-chest-press.DwioQn8l.gif",f="/SumUP/assets/lever-incline-chest-press.DMVVGLOW.gif",k="/SumUP/assets/lever-shoulder-press.B8R8WH_G.gif",x="/SumUP/assets/dumbbell-lateral-raise.DY2MIMfZ.gif",y="/SumUP/assets/cable-tricep-pushdown.DWheVMPu.gif",v="/SumUP/assets/cable-rope-overhead-tricep.UT7iTQVa.gif",S="/SumUP/assets/chest-shoulder-stretch.O_vVnTwx.gif",C="/SumUP/assets/dumbbell-squat.C5ccFYnq.gif",R="/SumUP/assets/smith-squat.WDOyJc6B.gif",U="/SumUP/assets/sled-leg-press.DZFlcE_w.gif",w="/SumUP/assets/barbell-romanian-deadlift.B41zBdf4.gif",B="/SumUP/assets/lever-leg-extension.DrsIR_F_.gif",E="/SumUP/assets/lever-lying-leg-curl.DvXXw-ts.gif",D="/SumUP/assets/lever-seated-calf-press.CwltNPDZ.gif",A="/SumUP/assets/quad-stretch.P23jrkAD.gif",T="/SumUP/assets/hamstring-stretch.CDyUz-7-.gif",F="/SumUP/assets/seated-glute-stretch.D6xG0lPn.gif",L="/SumUP/assets/seated-piriformis-stretch.BgmxqvKT.gif",O="/SumUP/assets/calf-stretch-wall.C96HG-zV.gif",Q=JSON.parse('{"title":"个人训练计划","description":"","frontmatter":{},"headers":[],"relativePath":"other/health/training-plan.md","filePath":"other/health/training-plan.md"}'),V={name:"other/health/training-plan.md"};function M(G,r,I,X,W,N){return i(),d("div",null,[...r[0]||(r[0]=[h(`<h1 id="个人训练计划" tabindex="-1">个人训练计划 <a class="header-anchor" href="#个人训练计划" aria-label="Permalink to &quot;个人训练计划&quot;">​</a></h1><blockquote><p><strong>定制对象</strong>：王振强 | 24岁 | 172cm / 69kg | 程序员 <strong>训练目标</strong>：匀称塑形 / 减脂 / 体态矫正（圆肩驼背） <strong>训练经验</strong>：7-8个月 | <strong>频率</strong>：一周 3-4 练 | <strong>每次时长</strong>：~60分钟 <strong>训练地点</strong>：商业健身房 | <strong>模式</strong>：推-拉-腿三分化（PPL）</p><p>⚠️ <strong>注意事项</strong>：有轻度肩部不适，所有推类动作需注意肩关节保护。每天包含肩外旋 + 面拉 矫正体态。</p></blockquote><hr><h2 id="📋-训练概览-循环模式" tabindex="-1">📋 训练概览：循环模式 <a class="header-anchor" href="#📋-训练概览-循环模式" aria-label="Permalink to &quot;📋 训练概览：循环模式&quot;">​</a></h2><blockquote><p><strong>本计划不绑定星期几。</strong> 你只需要按照「练一天 → 休一天 → 练下一天 → 休一天 → …」的节奏往下推进，像日历翻页一样，练到哪天就是哪天。</p></blockquote><h3 id="循环节奏" tabindex="-1">循环节奏 <a class="header-anchor" href="#循环节奏" aria-label="Permalink to &quot;循环节奏&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  练 ──→ 休 ──→ 练 ──→ 休 ──→ 练 ──→ 休 ──→ 练（可选）──→ 回到开头  │</span></span>
<span class="line"><span>│ 第1天     1天    第2天    1天    第3天    1天    第4天                │</span></span>
<span class="line"><span>│  拉日      休      推日      休      腿日      休    体态日            │</span></span>
<span class="line"><span>└──────────────────────────────────────────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><ul><li><strong>每次训练之间至少休息 1 天</strong>（让肌肉恢复）</li><li>腿日之后如果特别累，多休一天也没问题</li><li>一周大概走完 <strong>1.5 ~ 2 个循环</strong>（3-4 练），<strong>根据自己的精力和时间灵活安排</strong></li><li>这周忙只练了 2 次？没关系，下次进健身房接着上次的位置继续</li></ul><h3 id="四个训练日速览" tabindex="-1">四个训练日速览 <a class="header-anchor" href="#四个训练日速览" aria-label="Permalink to &quot;四个训练日速览&quot;">​</a></h3><table tabindex="0"><thead><tr><th>训练日</th><th>重点肌群</th><th>动作数</th><th>时长</th><th>一句话</th></tr></thead><tbody><tr><td><strong>第1天：拉日</strong></td><td>背阔肌、中上背、后束、二头</td><td>7个</td><td>60min</td><td>把背练宽练厚，对抗圆肩</td></tr><tr><td><strong>第2天：推日</strong></td><td>胸大肌、三角肌前中束、三头</td><td>7个</td><td>60min</td><td>注意肩膀保护，拉伸&gt;推胸</td></tr><tr><td><strong>第3天：腿日</strong></td><td>股四头肌、腘绳肌、臀大肌、小腿</td><td>7个</td><td>60min</td><td>下肢+核心，最累的一天</td></tr><tr><td><strong>第4天：体态日</strong></td><td>上背、后束、肩袖、核心、有氧</td><td>灵活</td><td>45-60min</td><td>可选，专门矫正久坐体态</td></tr></tbody></table><h3 id="两种走法-任选" tabindex="-1">两种走法，任选 <a class="header-anchor" href="#两种走法-任选" aria-label="Permalink to &quot;两种走法，任选&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>走法 A（3练/周，不走体态日）：</span></span>
<span class="line"><span>  拉 → 推 → 腿 → 拉 → 推 → 腿 → …</span></span>
<span class="line"><span></span></span>
<span class="line"><span>走法 B（4练/周，加入体态日）：</span></span>
<span class="line"><span>  拉 → 推 → 腿 → 体态 → 拉 → 推 → 腿 → 体态 → …</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><blockquote><p>💡 怎么知道下次练什么？<strong>记住上次练到第几天就行了。</strong> 比如今天练了推日（第2天），下次进健身房就是腿日（第3天）。 💡 如果超过 3 天没练，建议从拉日重新开始——背部激活对体态最重要。</p></blockquote><hr><h2 id="🔑-核心原则" tabindex="-1">🔑 核心原则 <a class="header-anchor" href="#🔑-核心原则" aria-label="Permalink to &quot;🔑 核心原则&quot;">​</a></h2><h3 id="体态矫正优先" tabindex="-1">体态矫正优先 <a class="header-anchor" href="#体态矫正优先" aria-label="Permalink to &quot;体态矫正优先&quot;">​</a></h3><p>作为程序员，每天久坐 10-12 小时，<strong>圆肩驼背</strong>是核心问题。本计划遵循以下策略：</p><ol><li><strong>每天训练前必做肩外旋 + 面拉</strong>：激活肩袖肌群，打开胸椎</li><li><strong>拉 &gt; 推</strong>：背部训练量始终大于胸部，平衡前后肌力</li><li><strong>胸肌必须拉伸</strong>：紧张缩短的胸肌是圆肩的元凶</li><li><strong>肩部保护</strong>：肩不舒服时，跳过所有过头推举，改为侧平举+前平举</li></ol><h3 id="渐进超负荷-progressive-overload" tabindex="-1">渐进超负荷（Progressive Overload） <a class="header-anchor" href="#渐进超负荷-progressive-overload" aria-label="Permalink to &quot;渐进超负荷（Progressive Overload）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>周数</th><th>策略</th></tr></thead><tbody><tr><td>第 1-2 周</td><td>适应期，RPE 6-7（留 3-4 个 reps 余力），专注动作质量</td></tr><tr><td>第 3-4 周</td><td>增重期，RPE 7-8（留 2-3 个 reps），小幅加重 2.5-5kg</td></tr><tr><td>第 5-6 周</td><td>挑战期，RPE 8-9（留 1-2 个 reps），尝试新重量</td></tr><tr><td>第 7 周</td><td><strong>减载周</strong>：重量降至 60-70%，组数减半，让身体恢复</td></tr><tr><td>第 8 周</td><td>新循环开始</td></tr></tbody></table><h3 id="休息规则" tabindex="-1">休息规则 <a class="header-anchor" href="#休息规则" aria-label="Permalink to &quot;休息规则&quot;">​</a></h3><ul><li><strong>组间休息</strong>：主项复合动作 90-120 秒，孤立动作 60-90 秒</li><li><strong>训练之间</strong>：每次训练后至少休 1 天。腿日（第3天）后如果特别酸，多休 1 天也无妨——循环不会因此「中断」，只是顺延</li><li><strong>循环不重置</strong>：哪怕休息了一周，回来也接着上次的进度走。如果断超过 10 天，建议从拉日重新开始让身体适应</li><li><strong>减载信号</strong>：连续两次训练感觉变弱/关节持续不适/睡眠质量下降 → 提前减载</li></ul><hr><h2 id="🔥-第一天-拉日-背部-后束-二头" tabindex="-1">🔥 第一天：拉日（背部 + 后束 + 二头） <a class="header-anchor" href="#🔥-第一天-拉日-背部-后束-二头" aria-label="Permalink to &quot;🔥 第一天：拉日（背部 + 后束 + 二头）&quot;">​</a></h2><h3 id="一、练前拉伸-热身-5-8-分钟" tabindex="-1">一、练前拉伸/热身（5-8 分钟） <a class="header-anchor" href="#一、练前拉伸-热身-5-8-分钟" aria-label="Permalink to &quot;一、练前拉伸/热身（5-8 分钟）&quot;">​</a></h3><blockquote><p>目标：激活肩袖、活动胸椎、预热背部肌群</p></blockquote><h4 id="_1-1-弹力带肩外旋" tabindex="-1">1.1 弹力带肩外旋 <a class="header-anchor" href="#_1-1-弹力带肩外旋" aria-label="Permalink to &quot;1.1 弹力带肩外旋&quot;">​</a></h4><p><img src="`+t+'" alt="肩外旋"></p><ul><li><strong>弹力带绑在固定物上</strong>，肘部夹紧身体呈 90°</li><li>向外旋转手臂，感受肩袖后侧发力</li><li><strong>2 组 × 15 次/侧</strong>，慢速控制（2 秒外旋 + 2 秒回程）</li><li>🎯 关键：<strong>肘部紧贴身体不离开</strong>，只旋转前臂</li></ul><h4 id="_1-2-弹力带反向飞鸟" tabindex="-1">1.2 弹力带反向飞鸟 <a class="header-anchor" href="#_1-2-弹力带反向飞鸟" aria-label="Permalink to &quot;1.2 弹力带反向飞鸟&quot;">​</a></h4><p><img src="'+a+'" alt="弹力带反向飞鸟"></p><ul><li>双手握住弹力带，手臂微屈，向两侧拉开</li><li>感受<strong>后束和上背中部</strong>的收缩</li><li><strong>2 组 × 15 次</strong>，顶峰收缩保持 1 秒</li><li>🎯 关键：肩胛骨主动后收，不是用手臂硬拉</li></ul><h4 id="_1-3-弹力带面拉-face-pull" tabindex="-1">1.3 弹力带面拉（Face Pull） <a class="header-anchor" href="#_1-3-弹力带面拉-face-pull" aria-label="Permalink to &quot;1.3 弹力带面拉（Face Pull）&quot;">​</a></h4><blockquote><p>⚠️ 本计划无对应 GIF，此处用文字描述，可参考弹力带反向飞鸟的轨迹</p></blockquote><ul><li>弹力带固定在面部高度，正握拉向面部</li><li>拉到底时手掌外旋（拇指向后），肘部向外打开</li><li><strong>2 组 × 15 次</strong></li><li>🎯 关键：<strong>面拉是对抗圆肩的第一动作</strong>，每次训练都做</li></ul><h4 id="_1-4-辅助引体向上-可选激活" tabindex="-1">1.4 辅助引体向上（可选激活） <a class="header-anchor" href="#_1-4-辅助引体向上-可选激活" aria-label="Permalink to &quot;1.4 辅助引体向上（可选激活）&quot;">​</a></h4><p><img src="'+g+'" alt="辅助引体向上"></p><ul><li>用弹力带辅助或器械辅助，<strong>2 组 × 5-8 次</strong></li><li>感受背阔肌发力，不是纯靠手臂</li></ul><hr><h3 id="二、正式训练动作-45-分钟" tabindex="-1">二、正式训练动作（~45 分钟） <a class="header-anchor" href="#二、正式训练动作-45-分钟" aria-label="Permalink to &quot;二、正式训练动作（~45 分钟）&quot;">​</a></h3><blockquote><p>⚡ 主项动作与辅助动作交替，主项重、辅助轻，避免过早力竭。</p></blockquote><hr><h4 id="🔷-a1-高位下拉-lat-pulldown-—-主项" tabindex="-1">🔷 A1. 高位下拉（Lat Pulldown）— 主项 <a class="header-anchor" href="#🔷-a1-高位下拉-lat-pulldown-—-主项" aria-label="Permalink to &quot;🔷 A1. 高位下拉（Lat Pulldown）— 主项&quot;">​</a></h4><p><img src="'+c+'" alt="高位下拉"></p><table tabindex="0"><thead><tr><th>项目</th><th>参数</th></tr></thead><tbody><tr><td><strong>组数 × 次数</strong></td><td>4 组 × 8-12 次</td></tr><tr><td><strong>RPE</strong></td><td>7-9</td></tr><tr><td><strong>握法</strong></td><td>宽握（比肩宽 1.5 倍）</td></tr><tr><td><strong>组间休息</strong></td><td>90 秒</td></tr></tbody></table><p><strong>动作讲解</strong>：</p><ol><li>坐稳，大腿卡在垫子下，<strong>挺胸沉肩</strong></li><li>正握横杆，握距约为肩宽的 1.5 倍</li><li>下拉时<strong>想象肘部向下向后拉</strong>，不是用手臂拽</li><li>拉到锁骨/上胸高度，顶峰收缩挤压背部 1 秒</li><li>慢速放回（2-3 秒），感受背阔肌被拉伸</li><li>身体不要过度后仰（后仰角度 &lt; 15°）</li></ol><p>🎯 <strong>重点关注</strong>：下拉时<strong>先启动肩胛骨下沉</strong>，再带动手臂。很多人用手臂拉而背部不动——如果你发现二头比背部先疲劳，减轻重量重新找发力感。</p><hr><h4 id="🔷-a2-坐姿绳索划船-seated-cable-row-—-主项" tabindex="-1">🔷 A2. 坐姿绳索划船（Seated Cable Row）— 主项 <a class="header-anchor" href="#🔷-a2-坐姿绳索划船-seated-cable-row-—-主项" aria-label="Permalink to &quot;🔷 A2. 坐姿绳索划船（Seated Cable Row）— 主项&quot;">​</a></h4><p><img src="'+l+'" alt="坐姿绳索划船"></p><table tabindex="0"><thead><tr><th>项目</th><th>参数</th></tr></thead><tbody><tr><td><strong>组数 × 次数</strong></td><td>4 组 × 10-12 次</td></tr><tr><td><strong>RPE</strong></td><td>7-9</td></tr><tr><td><strong>握把</strong></td><td>V 型把手或绳索</td></tr><tr><td><strong>组间休息</strong></td><td>90 秒</td></tr></tbody></table><p><strong>动作讲解</strong>：</p><ol><li>坐于划船凳上，双脚踩稳踏板，膝盖微屈</li><li>背部保持直立，<strong>不弯腰、不前倾</strong></li><li>拉向腹部时，<strong>肘部贴近身体向后滑</strong>，肩胛骨夹紧</li><li>顶峰收缩 1 秒，想象背部中间夹一支笔</li><li>慢速放回（2 秒），手臂不完全伸直以保持背部张力</li></ol><p>🎯 <strong>重点关注</strong>：全程<strong>背部始终挺直</strong>！弯腰是划船中最常见的错误，容易伤腰。如果腰部撑不住，减轻重量。</p><hr><h4 id="🔷-b1-哑铃俯身划船-bent-over-row-—-辅助" tabindex="-1">🔷 B1. 哑铃俯身划船（Bent Over Row）— 辅助 <a class="header-anchor" href="#🔷-b1-哑铃俯身划船-bent-over-row-—-辅助" aria-label="Permalink to &quot;🔷 B1. 哑铃俯身划船（Bent Over Row）— 辅助&quot;">​</a></h4><p><img src="'+b+'" alt="哑铃俯身划船"></p><table tabindex="0"><thead><tr><th>项目</th><th>参数</th></tr></thead><tbody><tr><td><strong>组数 × 次数</strong></td><td>3 组 × 10-12 次/侧</td></tr><tr><td><strong>RPE</strong></td><td>7-8</td></tr><tr><td><strong>组间休息</strong></td><td>60-90 秒</td></tr></tbody></table><p><strong>动作讲解</strong>：</p><ol><li>单手撑凳，同侧膝跪凳，另一手持哑铃</li><li>背部与地面接近平行，保持中立</li><li>将哑铃拉向腰部，<strong>肘部贴近身体</strong></li><li>顶峰收缩 1 秒，缓慢下放</li><li>先用轻重量掌握发力感，再加重量</li></ol><p>🎯 <strong>重点关注</strong>：这个动作对单侧背部发展极好，可以发现并纠正左右不平衡。<strong>拉到最顶端时背部应该完全收紧</strong>。</p><hr><h4 id="🔷-b2-哑铃反向飞鸟-reverse-fly-—-后束" tabindex="-1">🔷 B2. 哑铃反向飞鸟（Reverse Fly）— 后束 <a class="header-anchor" href="#🔷-b2-哑铃反向飞鸟-reverse-fly-—-后束" aria-label="Permalink to &quot;🔷 B2. 哑铃反向飞鸟（Reverse Fly）— 后束&quot;">​</a></h4><p><img src="'+s+'" alt="哑铃反向飞鸟"></p><table tabindex="0"><thead><tr><th>项目</th><th>参数</th></tr></thead><tbody><tr><td><strong>组数 × 次数</strong></td><td>3 组 × 12-15 次</td></tr><tr><td><strong>RPE</strong></td><td>6-8</td></tr><tr><td><strong>组间休息</strong></td><td>60 秒</td></tr></tbody></table><p><strong>动作讲解</strong>：</p><ol><li>坐在凳子上，俯身至胸部接近大腿，双手持轻哑铃（建议 <strong>2-4kg 起步</strong>）</li><li>手臂微屈（不要锁死），向两侧抬起</li><li>想象<strong>拇指指向天花板</strong>，感受后束收缩</li><li>顶峰保持 1 秒，慢速下放</li><li><strong>重量不要大！后束是小肌群，靠控制和次数，不靠重量</strong></li></ol><p>🎯 <strong>重点关注</strong>：后束是改善圆肩的关键！后束弱 → 肩胛骨前引 → 圆肩。<strong>这个动作比你想的更重要</strong>。</p><hr><h4 id="🔷-c1-直臂下压-straight-arm-pulldown-—-背阔肌收尾" tabindex="-1">🔷 C1. 直臂下压（Straight Arm Pulldown）— 背阔肌收尾 <a class="header-anchor" href="#🔷-c1-直臂下压-straight-arm-pulldown-—-背阔肌收尾" aria-label="Permalink to &quot;🔷 C1. 直臂下压（Straight Arm Pulldown）— 背阔肌收尾&quot;">​</a></h4><p><img src="'+p+'" alt="直臂下压"></p><table tabindex="0"><thead><tr><th>项目</th><th>参数</th></tr></thead><tbody><tr><td><strong>组数 × 次数</strong></td><td>3 组 × 12-15 次</td></tr><tr><td><strong>RPE</strong></td><td>6-8</td></tr><tr><td><strong>组间休息</strong></td><td>60 秒</td></tr></tbody></table><p><strong>动作讲解</strong>：</p><ol><li>站于高位龙门架前，双手正握直杆</li><li>手臂基本伸直（微屈不锁死），从肩高位置向下压至大腿前</li><li>发力时<strong>想象背阔肌收缩</strong>，不是耸肩下压</li><li>回程时控制（2 秒），手臂不超过肩高</li></ol><p>🎯 <strong>重点关注</strong>：全程手臂角度不变，靠<strong>背阔肌发力</strong>不是靠身体下压。这是背阔肌的孤立收尾动作，建立背阔肌的神经连接。</p><hr><h4 id="🔷-c2-哑铃弯举-biceps-curl-—-二头" tabindex="-1">🔷 C2. 哑铃弯举（Biceps Curl）— 二头 <a class="header-anchor" href="#🔷-c2-哑铃弯举-biceps-curl-—-二头" aria-label="Permalink to &quot;🔷 C2. 哑铃弯举（Biceps Curl）— 二头&quot;">​</a></h4><p><img src="'+u+'" alt="哑铃弯举"></p><table tabindex="0"><thead><tr><th>项目</th><th>参数</th></tr></thead><tbody><tr><td><strong>组数 × 次数</strong></td><td>3 组 × 10-12 次/侧</td></tr><tr><td><strong>RPE</strong></td><td>7-8</td></tr><tr><td><strong>组间休息</strong></td><td>60 秒</td></tr></tbody></table><p><strong>动作讲解</strong>：</p><ol><li>站姿或坐姿，双手持哑铃，掌心朝前</li><li>肘部固定在大腿或身体两侧，<strong>不要摆动借力</strong></li><li>弯举至顶峰，挤压二头肌 1 秒</li><li>慢速下放（2-3 秒），离心过程比向心更重要</li></ol><p>🎯 <strong>重点关注</strong>：如果身体开始晃 → 重量太大。二头肌是小肌群，<strong>控制和离心比重量更重要</strong>。</p><hr><h4 id="🔷-c3-绳索弯举-cable-curl-—-二头收尾" tabindex="-1">🔷 C3. 绳索弯举（Cable Curl）— 二头收尾 <a class="header-anchor" href="#🔷-c3-绳索弯举-cable-curl-—-二头收尾" aria-label="Permalink to &quot;🔷 C3. 绳索弯举（Cable Curl）— 二头收尾&quot;">​</a></h4><p><img src="'+m+'" alt="绳索弯举"></p><table tabindex="0"><thead><tr><th>项目</th><th>参数</th></tr></thead><tbody><tr><td><strong>组数 × 次数</strong></td><td>3 组 × 12-15 次</td></tr><tr><td><strong>RPE</strong></td><td>6-8</td></tr><tr><td><strong>组间休息</strong></td><td>45-60 秒</td></tr></tbody></table><p><strong>动作讲解</strong>：</p><ol><li>站于低位龙门架前，双手正握直杆/绳索</li><li>肘部贴紧身体两侧，弯举至肩高</li><li>慢速下放，保持二头持续张力</li><li>绳索带来的恒定张力，比哑铃更持续刺激</li></ol><p>🎯 <strong>重点关注</strong>：绳索在整个行程中都提供阻力（不像哑铃在某些角度失去张力），是二头肌很好的收尾动作。</p><hr><h3 id="三、练后拉伸-5-分钟" tabindex="-1">三、练后拉伸（5 分钟） <a class="header-anchor" href="#三、练后拉伸-5-分钟" aria-label="Permalink to &quot;三、练后拉伸（5 分钟）&quot;">​</a></h3><blockquote><p>目标：恢复背部/手臂肌群长度，打开胸椎</p></blockquote><h4 id="_3-1-背阔肌拉伸" tabindex="-1">3.1 背阔肌拉伸 <a class="header-anchor" href="#_3-1-背阔肌拉伸" aria-label="Permalink to &quot;3.1 背阔肌拉伸&quot;">​</a></h4><p><img src="'+o+'" alt="背阔肌拉伸"></p><ul><li>跪姿或站姿，双手抓住固定物</li><li>臀部向后坐，感受背阔肌/大圆肌的拉伸</li><li><strong>每侧保持 30 秒 × 2 组</strong></li></ul><h4 id="_3-2-上背拉伸" tabindex="-1">3.2 上背拉伸 <a class="header-anchor" href="#_3-2-上背拉伸" aria-label="Permalink to &quot;3.2 上背拉伸&quot;">​</a></h4><p><img src="'+q+'" alt="上背拉伸"></p><ul><li>双手交叉于胸前，拱背含胸</li><li>感受肩胛骨之间的拉伸</li><li><strong>保持 30 秒 × 2 组</strong></li></ul><h4 id="_3-3-胸背拉伸" tabindex="-1">3.3 胸背拉伸 <a class="header-anchor" href="#_3-3-胸背拉伸" aria-label="Permalink to &quot;3.3 胸背拉伸&quot;">​</a></h4><p><img src="'+P+'" alt="胸背拉伸"></p><ul><li>双手背后交叉，肩胛骨向后夹紧</li><li>同时抬头挺胸，打开胸腔</li><li><strong>保持 20 秒，做 3 次</strong></li></ul><hr><h2 id="🔥-第二天-推日-胸部-肩部-三头" tabindex="-1">🔥 第二天：推日（胸部 + 肩部 + 三头） <a class="header-anchor" href="#🔥-第二天-推日-胸部-肩部-三头" aria-label="Permalink to &quot;🔥 第二天：推日（胸部 + 肩部 + 三头）&quot;">​</a></h2><h3 id="一、练前拉伸-热身-5-8-分钟-1" tabindex="-1">一、练前拉伸/热身（5-8 分钟） <a class="header-anchor" href="#一、练前拉伸-热身-5-8-分钟-1" aria-label="Permalink to &quot;一、练前拉伸/热身（5-8 分钟）&quot;">​</a></h3><blockquote><p>⚠️ 推日热身尤其重要！肩膀有不适时更要充分热身。</p></blockquote><h4 id="_1-1-弹力带肩外旋-1" tabindex="-1">1.1 弹力带肩外旋 <a class="header-anchor" href="#_1-1-弹力带肩外旋-1" aria-label="Permalink to &quot;1.1 弹力带肩外旋&quot;">​</a></h4><p><img src="'+t+'" alt="肩外旋"></p><ul><li><strong>3 组 × 15 次/侧</strong>（推日多加一组保护肩袖）</li><li>动作同拉日</li></ul><h4 id="_1-2-胸部动态拉伸" tabindex="-1">1.2 胸部动态拉伸 <a class="header-anchor" href="#_1-2-胸部动态拉伸" aria-label="Permalink to &quot;1.2 胸部动态拉伸&quot;">​</a></h4><p><img src="'+e+'" alt="胸部动态拉伸"></p><ul><li>双手向两侧展开，动态向后伸展</li><li>感受胸肌和肩前部的拉伸</li><li><strong>1 组 × 10 次</strong>，逐渐加大幅度</li></ul><h4 id="_1-3-弹力带反向飞鸟-激活后束-打开胸椎" tabindex="-1">1.3 弹力带反向飞鸟（激活后束 + 打开胸椎） <a class="header-anchor" href="#_1-3-弹力带反向飞鸟-激活后束-打开胸椎" aria-label="Permalink to &quot;1.3 弹力带反向飞鸟（激活后束 + 打开胸椎）&quot;">​</a></h4><p><img src="'+a+'" alt="弹力带反向飞鸟"></p><ul><li><strong>2 组 × 15 次</strong></li><li>推日前激活后束，帮助在推的动作中稳定肩胛骨</li></ul><h4 id="_1-4-弹力带面拉-face-pull" tabindex="-1">1.4 弹力带面拉（Face Pull） <a class="header-anchor" href="#_1-4-弹力带面拉-face-pull" aria-label="Permalink to &quot;1.4 弹力带面拉（Face Pull）&quot;">​</a></h4><ul><li><strong>2 组 × 15 次</strong>（同拉日）</li></ul><hr><h3 id="二、正式训练动作-45-分钟-1" tabindex="-1">二、正式训练动作（~45 分钟） <a class="header-anchor" href="#二、正式训练动作-45-分钟-1" aria-label="Permalink to &quot;二、正式训练动作（~45 分钟）&quot;">​</a></h3><hr><h4 id="🔷-a1-器械推胸-chest-press-machine-—-主项" tabindex="-1">🔷 A1. 器械推胸（Chest Press Machine）— 主项 <a class="header-anchor" href="#🔷-a1-器械推胸-chest-press-machine-—-主项" aria-label="Permalink to &quot;🔷 A1. 器械推胸（Chest Press Machine）— 主项&quot;">​</a></h4><p><img src="'+_+'" alt="器械推胸"></p><table tabindex="0"><thead><tr><th>项目</th><th>参数</th></tr></thead><tbody><tr><td><strong>组数 × 次数</strong></td><td>4 组 × 8-12 次</td></tr><tr><td><strong>RPE</strong></td><td>7-9</td></tr><tr><td><strong>组间休息</strong></td><td>90 秒</td></tr></tbody></table><p><strong>动作讲解</strong>：</p><ol><li>调整座椅高度，使<strong>握把与胸部下缘对齐</strong>（非肩膀高度）</li><li>背部贴紧靠垫，肩胛骨后收下沉</li><li>推的时候<strong>不要耸肩</strong>，肩胛骨始终保持后收贴凳</li><li>推到手臂接近伸直（不要锁死肘关节）</li><li>回程时控制（2-3 秒），手肘不超过身体平面</li><li>感受<strong>胸肌的挤压</strong>，不是肩膀前束的推动</li></ol><p>🎯 <strong>重点关注</strong>：选择器械而非杠铃卧推的原因——你的肩部有不适，器械轨迹固定更安全。<strong>如果推的时候肩膀前侧疼，降低重量 + 缩减动作幅度</strong>（不要把手肘拉得太靠后）。</p><hr><h4 id="🔷-a2-上斜器械推胸-incline-chest-press-—-上胸" tabindex="-1">🔷 A2. 上斜器械推胸（Incline Chest Press）— 上胸 <a class="header-anchor" href="#🔷-a2-上斜器械推胸-incline-chest-press-—-上胸" aria-label="Permalink to &quot;🔷 A2. 上斜器械推胸（Incline Chest Press）— 上胸&quot;">​</a></h4><p><img src="'+f+'" alt="上斜器械推胸"></p><table tabindex="0"><thead><tr><th>项目</th><th>参数</th></tr></thead><tbody><tr><td><strong>组数 × 次数</strong></td><td>3 组 × 10-12 次</td></tr><tr><td><strong>RPE</strong></td><td>7-8</td></tr><tr><td><strong>组间休息</strong></td><td>75-90 秒</td></tr></tbody></table><p><strong>动作讲解</strong>：</p><ol><li>使用上斜推胸器械，角度约 30-45°</li><li>调整握把位置，发力轨迹朝向前上方</li><li>推到顶端时感受<strong>上胸肌</strong>的收缩</li><li>回程控制，不要借助反弹力</li></ol><p>🎯 <strong>重点关注</strong>：上胸是很多人（尤其是久坐族）的弱项。上胸发展好，侧面看胸部更饱满，视觉上体态也更挺拔。</p><hr><h4 id="🔷-b1-器械推肩-shoulder-press-machine-—-肩部主项" tabindex="-1">🔷 B1. 器械推肩（Shoulder Press Machine）— 肩部主项 <a class="header-anchor" href="#🔷-b1-器械推肩-shoulder-press-machine-—-肩部主项" aria-label="Permalink to &quot;🔷 B1. 器械推肩（Shoulder Press Machine）— 肩部主项&quot;">​</a></h4><p><img src="'+k+'" alt="器械推肩"></p><table tabindex="0"><thead><tr><th>项目</th><th>参数</th></tr></thead><tbody><tr><td><strong>组数 × 次数</strong></td><td>3 组 × 10-12 次</td></tr><tr><td><strong>RPE</strong></td><td>6-8</td></tr><tr><td><strong>组间休息</strong></td><td>75 秒</td></tr></tbody></table><blockquote><p>⚠️ <strong>肩部保护提示</strong>：如果推肩时肩关节有刺痛或弹响伴随疼痛 → <strong>立即停止，跳过此动作</strong>，改为做多两组侧平举。</p></blockquote><p><strong>动作讲解</strong>：</p><ol><li>调整座椅，握把与肩膀高度对齐</li><li>上推时避免<strong>完全锁死肘关节</strong></li><li>下放时手肘不超过肩膀平面以下（减少肩关节压力）</li><li>全程控制，不要借力</li><li>整个过程中<strong>肩胛骨保持稳定</strong></li></ol><p>🎯 <strong>重点关注</strong>：器械推肩比哑铃/杠铃推肩更安全，因为轨迹固定，不易出现代偿。<strong>如果今天肩膀感觉不好，用轻重量做 15-20 次高次数即可</strong>。</p><hr><h4 id="🔷-b2-哑铃侧平举-lateral-raise-—-中束" tabindex="-1">🔷 B2. 哑铃侧平举（Lateral Raise）— 中束 <a class="header-anchor" href="#🔷-b2-哑铃侧平举-lateral-raise-—-中束" aria-label="Permalink to &quot;🔷 B2. 哑铃侧平举（Lateral Raise）— 中束&quot;">​</a></h4><p><img src="'+x+'" alt="哑铃侧平举"></p><table tabindex="0"><thead><tr><th>项目</th><th>参数</th></tr></thead><tbody><tr><td><strong>组数 × 次数</strong></td><td>3 组 × 12-15 次</td></tr><tr><td><strong>RPE</strong></td><td>6-8</td></tr><tr><td><strong>组间休息</strong></td><td>60 秒</td></tr></tbody></table><p><strong>动作讲解</strong>：</p><ol><li>双手持轻哑铃（建议 <strong>2-5kg 起步</strong>），站姿或坐姿</li><li>手臂微屈，从身体两侧抬起至与地面平行</li><li>想象<strong>倒水壶的动作</strong>——小拇指侧略高，像在倒水</li><li>顶峰保持 1 秒，慢速下放（2-3 秒）</li><li>**不要借力摆动！**纯靠中束发力</li></ol><p>🎯 <strong>重点关注</strong>：侧平举是最容易「借力」的动作之一。重量小不丢人——用 2kg 做到完美控制，比用 8kg 甩上去有效 10 倍。另外，<strong>抬起时肘部先于手腕启动</strong>，让中束主导发力。</p><hr><h4 id="🔷-c1-绳索下压-tricep-pushdown-—-三头" tabindex="-1">🔷 C1. 绳索下压（Tricep Pushdown）— 三头 <a class="header-anchor" href="#🔷-c1-绳索下压-tricep-pushdown-—-三头" aria-label="Permalink to &quot;🔷 C1. 绳索下压（Tricep Pushdown）— 三头&quot;">​</a></h4><p><img src="'+y+'" alt="绳索下压"></p><table tabindex="0"><thead><tr><th>项目</th><th>参数</th></tr></thead><tbody><tr><td><strong>组数 × 次数</strong></td><td>3 组 × 12-15 次</td></tr><tr><td><strong>RPE</strong></td><td>7-8</td></tr><tr><td><strong>组间休息</strong></td><td>60 秒</td></tr></tbody></table><p><strong>动作讲解</strong>：</p><ol><li>站于高位龙门架前，正握直杆或绳索</li><li><strong>肘部紧贴身体两侧</strong>，下压至手臂伸直</li><li>顶峰停顿 1 秒，挤压三头肌</li><li>回程时前臂回到约 90°，不让配重片落下</li><li><strong>全程肘部不移动</strong></li></ol><p>🎯 <strong>重点关注</strong>：很多人做这个动作时肘部会前后摆动——这是借力。<strong>肘部固定是唯一要点</strong>。</p><hr><h4 id="🔷-c2-绳索过头臂屈伸-overhead-tricep-extension-—-三头长头" tabindex="-1">🔷 C2. 绳索过头臂屈伸（Overhead Tricep Extension）— 三头长头 <a class="header-anchor" href="#🔷-c2-绳索过头臂屈伸-overhead-tricep-extension-—-三头长头" aria-label="Permalink to &quot;🔷 C2. 绳索过头臂屈伸（Overhead Tricep Extension）— 三头长头&quot;">​</a></h4><p><img src="'+v+'" alt="绳索过头臂屈伸"></p><table tabindex="0"><thead><tr><th>项目</th><th>参数</th></tr></thead><tbody><tr><td><strong>组数 × 次数</strong></td><td>3 组 × 12-15 次</td></tr><tr><td><strong>RPE</strong></td><td>6-8</td></tr><tr><td><strong>组间休息</strong></td><td>45-60 秒</td></tr></tbody></table><p><strong>动作讲解</strong>：</p><ol><li>背对龙门架，双手拉绳索过头</li><li>从颈后向前伸展手臂，感受三头肌长头的收缩</li><li>手臂伸直后停顿 1 秒</li><li>慢速回到起始位</li></ol><p>🎯 <strong>重点关注</strong>：这个动作刺激三头肌的长头，是三头肌中体积最大的部分。<strong>注意不要用太重</strong>，否则容易耸肩借力。</p><hr><h3 id="三、练后拉伸-5-分钟-1" tabindex="-1">三、练后拉伸（5 分钟） <a class="header-anchor" href="#三、练后拉伸-5-分钟-1" aria-label="Permalink to &quot;三、练后拉伸（5 分钟）&quot;">​</a></h3><h4 id="_3-1-胸部动态拉伸" tabindex="-1">3.1 胸部动态拉伸 <a class="header-anchor" href="#_3-1-胸部动态拉伸" aria-label="Permalink to &quot;3.1 胸部动态拉伸&quot;">​</a></h4><p><img src="'+e+'" alt="胸部动态拉伸"></p><ul><li><strong>保持 30 秒 × 2 组</strong></li></ul><h4 id="_3-2-胸部与肩前拉伸" tabindex="-1">3.2 胸部与肩前拉伸 <a class="header-anchor" href="#_3-2-胸部与肩前拉伸" aria-label="Permalink to &quot;3.2 胸部与肩前拉伸&quot;">​</a></h4><p><img src="'+S+'" alt="胸部与肩前拉伸"></p><ul><li>手扶墙或门框，身体前倾旋转</li><li>感受胸肌和三角肌前束的拉伸</li><li><strong>每侧保持 30 秒 × 2 组</strong></li></ul><blockquote><p>推日后胸肌拉伸极其重要！紧张的胸肌会加重圆肩。<strong>多做 1 组胸肌拉伸，对你比多练 1 组推胸更有价值</strong>。</p></blockquote><h4 id="_3-3-背阔肌拉伸" tabindex="-1">3.3 背阔肌拉伸 <a class="header-anchor" href="#_3-3-背阔肌拉伸" aria-label="Permalink to &quot;3.3 背阔肌拉伸&quot;">​</a></h4><p><img src="'+o+'" alt="背阔肌拉伸"></p><ul><li><strong>每侧保持 30 秒 × 2 组</strong></li></ul><hr><h2 id="🔥-第三天-腿日-下肢-核心" tabindex="-1">🔥 第三天：腿日（下肢 + 核心） <a class="header-anchor" href="#🔥-第三天-腿日-下肢-核心" aria-label="Permalink to &quot;🔥 第三天：腿日（下肢 + 核心）&quot;">​</a></h2><h3 id="一、练前拉伸-热身-5-8-分钟-2" tabindex="-1">一、练前拉伸/热身（5-8 分钟） <a class="header-anchor" href="#一、练前拉伸-热身-5-8-分钟-2" aria-label="Permalink to &quot;一、练前拉伸/热身（5-8 分钟）&quot;">​</a></h3><blockquote><p>腿日热身重点是<strong>打开髋关节 + 激活臀部</strong>，久坐族的髋屈肌通常很紧。</p></blockquote><h4 id="_1-1-自重深蹲-预热动作模式" tabindex="-1">1.1 自重深蹲（预热动作模式） <a class="header-anchor" href="#_1-1-自重深蹲-预热动作模式" aria-label="Permalink to &quot;1.1 自重深蹲（预热动作模式）&quot;">​</a></h4><p><img src="'+C+'" alt="哑铃深蹲"></p><ul><li>不负重，仅做动作模式预热</li><li>手臂前伸保持平衡，缓慢下蹲，底部停顿 2 秒</li><li><strong>1 组 × 10 次</strong></li></ul><h4 id="_1-2-弹力带臀桥-激活臀部" tabindex="-1">1.2 弹力带臀桥（激活臀部） <a class="header-anchor" href="#_1-2-弹力带臀桥-激活臀部" aria-label="Permalink to &quot;1.2 弹力带臀桥（激活臀部）&quot;">​</a></h4><ul><li>弹力带套在膝盖上方，仰卧做臀桥</li><li>膝盖向外对抗弹力带，激活臀中肌</li><li><strong>2 组 × 15 次</strong></li></ul><h4 id="_1-3-弹力带肩外旋" tabindex="-1">1.3 弹力带肩外旋 <a class="header-anchor" href="#_1-3-弹力带肩外旋" aria-label="Permalink to &quot;1.3 弹力带肩外旋&quot;">​</a></h4><p><img src="'+t+'" alt="肩外旋"></p><ul><li><strong>2 组 × 15 次/侧</strong>（每天做！）</li></ul><h4 id="_1-4-腿摆动-动态拉伸髋关节" tabindex="-1">1.4 腿摆动（动态拉伸髋关节） <a class="header-anchor" href="#_1-4-腿摆动-动态拉伸髋关节" aria-label="Permalink to &quot;1.4 腿摆动（动态拉伸髋关节）&quot;">​</a></h4><ul><li>手扶固定物，单腿前后/左右摆动</li><li><strong>前后 × 10 次/侧 + 左右 × 10 次/侧</strong></li></ul><hr><h3 id="二、正式训练动作-45-分钟-2" tabindex="-1">二、正式训练动作（~45 分钟） <a class="header-anchor" href="#二、正式训练动作-45-分钟-2" aria-label="Permalink to &quot;二、正式训练动作（~45 分钟）&quot;">​</a></h3><hr><h4 id="🔷-a1-史密斯深蹲-smith-machine-squat-—-主项" tabindex="-1">🔷 A1. 史密斯深蹲（Smith Machine Squat）— 主项 <a class="header-anchor" href="#🔷-a1-史密斯深蹲-smith-machine-squat-—-主项" aria-label="Permalink to &quot;🔷 A1. 史密斯深蹲（Smith Machine Squat）— 主项&quot;">​</a></h4><p><img src="'+R+'" alt="史密斯深蹲"></p><table tabindex="0"><thead><tr><th>项目</th><th>参数</th></tr></thead><tbody><tr><td><strong>组数 × 次数</strong></td><td>4 组 × 8-12 次</td></tr><tr><td><strong>RPE</strong></td><td>7-9</td></tr><tr><td><strong>组间休息</strong></td><td>90-120 秒</td></tr></tbody></table><p><strong>动作讲解</strong>：</p><ol><li>杠铃放在<strong>斜方肌上方</strong>（不是颈椎！），双脚略宽于肩，脚尖微外八</li><li>史密斯机轨迹是斜后方的，顺着轨迹下蹲</li><li>下蹲时<strong>挺胸、收紧核心</strong>，像坐在一把看不见的椅子上</li><li>大腿至少蹲到与地面平行（幅度不够效果打折）</li><li>推起时臀部主动发力，膝盖不要内扣</li><li>全程<strong>膝盖方向与脚尖方向一致</strong></li></ol><p>🎯 <strong>重点关注</strong>：选择史密斯而非自由深蹲——你的训练经验（7-8 个月）+ 久坐髋屈肌紧张，史密斯更安全。<strong>如果蹲不下去（脚踝灵活度不够），在脚后跟垫 2.5kg 的杠铃片</strong>。</p><hr><h4 id="🔷-a2-腿举-leg-press" tabindex="-1">🔷 A2. 腿举（Leg Press） <a class="header-anchor" href="#🔷-a2-腿举-leg-press" aria-label="Permalink to &quot;🔷 A2. 腿举（Leg Press）&quot;">​</a></h4><p><img src="'+U+'" alt="腿举"></p><table tabindex="0"><thead><tr><th>项目</th><th>参数</th></tr></thead><tbody><tr><td><strong>组数 × 次数</strong></td><td>3 组 × 10-15 次</td></tr><tr><td><strong>RPE</strong></td><td>7-8</td></tr><tr><td><strong>组间休息</strong></td><td>75-90 秒</td></tr></tbody></table><p><strong>动作讲解</strong>：</p><ol><li>坐稳靠背，双脚与肩同宽置于踏板上</li><li>推出时<strong>不要完全锁死膝盖</strong>（留一点微屈）</li><li>下降时大腿至少与踏板平行，但不要让臀部离开靠背</li><li>全程腰背贴紧靠背，不要因为太重而让下背离开</li></ol><p>🎯 <strong>重点关注</strong>：腿举是安全的大重量动作，但<strong>下放太低会让下背离开靠背→伤腰</strong>。宁可缩减幅度，也不要让臀部抬起来。</p><hr><h4 id="🔷-b1-罗马尼亚硬拉-romanian-deadlift-—-腘绳肌-臀" tabindex="-1">🔷 B1. 罗马尼亚硬拉（Romanian Deadlift）— 腘绳肌+臀 <a class="header-anchor" href="#🔷-b1-罗马尼亚硬拉-romanian-deadlift-—-腘绳肌-臀" aria-label="Permalink to &quot;🔷 B1. 罗马尼亚硬拉（Romanian Deadlift）— 腘绳肌+臀&quot;">​</a></h4><p><img src="'+w+'" alt="罗马尼亚硬拉"></p><table tabindex="0"><thead><tr><th>项目</th><th>参数</th></tr></thead><tbody><tr><td><strong>组数 × 次数</strong></td><td>3 组 × 10-12 次</td></tr><tr><td><strong>RPE</strong></td><td>7-8</td></tr><tr><td><strong>组间休息</strong></td><td>75-90 秒</td></tr></tbody></table><p><strong>动作讲解</strong>：</p><ol><li>双手持杠铃（或哑铃），站距与臀同宽</li><li><strong>膝盖微屈不锁死</strong>，臀部向后推（想象用屁股关门）</li><li>杠铃沿大腿前侧下滑，背部全程挺直</li><li>下降到膝盖下方、腘绳肌感到强烈拉伸时停止</li><li>臀部收紧发力回到起始位</li></ol><p>🎯 <strong>重点关注</strong>：罗马尼亚硬拉不是传统硬拉——<strong>膝盖弯曲幅度很小</strong>，主要是髋关节铰链动作。全程背部挺直！<strong>如果弯腰 → 重量太大</strong>。这是腘绳肌和臀大肌的王牌动作，对改善久坐族的「臀肌失忆」极有帮助。</p><hr><h4 id="🔷-b2-腿屈伸-leg-extension-—-股四头肌孤立" tabindex="-1">🔷 B2. 腿屈伸（Leg Extension）— 股四头肌孤立 <a class="header-anchor" href="#🔷-b2-腿屈伸-leg-extension-—-股四头肌孤立" aria-label="Permalink to &quot;🔷 B2. 腿屈伸（Leg Extension）— 股四头肌孤立&quot;">​</a></h4><p><img src="'+B+'" alt="腿屈伸"></p><table tabindex="0"><thead><tr><th>项目</th><th>参数</th></tr></thead><tbody><tr><td><strong>组数 × 次数</strong></td><td>3 组 × 12-15 次</td></tr><tr><td><strong>RPE</strong></td><td>7-8</td></tr><tr><td><strong>组间休息</strong></td><td>60 秒</td></tr></tbody></table><p><strong>动作讲解</strong>：</p><ol><li>调整靠背使膝关节旋转轴与器械轴对齐</li><li>小腿垫在脚踝上方（不是胫骨中部）</li><li>匀速伸展至膝盖接近伸直（不要锁死）</li><li>顶峰收缩股四头肌 1 秒，慢速下放（3 秒）</li></ol><p>🎯 <strong>重点关注</strong>：<strong>离心（下放）比向心（抬起）更重要</strong>，离心阶段控制 3 秒。这个动作可以很好地找到股四头肌的发力感。</p><hr><h4 id="🔷-c1-腿弯举-leg-curl-—-腘绳肌孤立" tabindex="-1">🔷 C1. 腿弯举（Leg Curl）— 腘绳肌孤立 <a class="header-anchor" href="#🔷-c1-腿弯举-leg-curl-—-腘绳肌孤立" aria-label="Permalink to &quot;🔷 C1. 腿弯举（Leg Curl）— 腘绳肌孤立&quot;">​</a></h4><p><img src="'+E+'" alt="腿弯举"></p><table tabindex="0"><thead><tr><th>项目</th><th>参数</th></tr></thead><tbody><tr><td><strong>组数 × 次数</strong></td><td>3 组 × 12-15 次</td></tr><tr><td><strong>RPE</strong></td><td>7-8</td></tr><tr><td><strong>组间休息</strong></td><td>60 秒</td></tr></tbody></table><p><strong>动作讲解</strong>：</p><ol><li>俯卧在腿弯举器上，膝盖略超出凳子边缘</li><li>小腿垫在脚踝后上方，抓住把手稳定身体</li><li>弯举至最大限度挤压腘绳肌</li><li>顶峰保持 1 秒，慢速下放（3 秒）</li><li><strong>臀部不要因为太重而翘起来</strong></li></ol><p>🎯 <strong>重点关注</strong>：腘绳肌是多数人的弱项，也是改善体态的关键——强壮的腘绳肌可以稳定骨盆，减少下背代偿。<strong>不追求大重量，追求强烈的肌肉感受</strong>。</p><hr><h4 id="🔷-c2-坐姿提踵-seated-calf-raise-—-小腿" tabindex="-1">🔷 C2. 坐姿提踵（Seated Calf Raise）— 小腿 <a class="header-anchor" href="#🔷-c2-坐姿提踵-seated-calf-raise-—-小腿" aria-label="Permalink to &quot;🔷 C2. 坐姿提踵（Seated Calf Raise）— 小腿&quot;">​</a></h4><p><img src="'+D+'" alt="坐姿提踵"></p><table tabindex="0"><thead><tr><th>项目</th><th>参数</th></tr></thead><tbody><tr><td><strong>组数 × 次数</strong></td><td>4 组 × 12-20 次</td></tr><tr><td><strong>RPE</strong></td><td>7-9</td></tr><tr><td><strong>组间休息</strong></td><td>45-60 秒</td></tr></tbody></table><p><strong>动作讲解</strong>：</p><ol><li>膝关节呈 90°，前脚掌踩在踏板上</li><li>尽可能高地踮起脚尖，顶峰保持 2 秒</li><li>慢速下放至脚后跟低于踏板，感受小腿拉伸</li><li><strong>全程大范围活动</strong>：从最大拉伸位到最大收缩位</li></ol><p>🎯 <strong>重点关注</strong>：小腿肌群需要高容量 + 大范围活动才肯长。每次做到真正力竭。<strong>坐姿更针对比目鱼肌（厚度），站姿更针对腓肠肌（长度）</strong>。</p><hr><h3 id="三、练后拉伸-5-分钟-2" tabindex="-1">三、练后拉伸（5 分钟） <a class="header-anchor" href="#三、练后拉伸-5-分钟-2" aria-label="Permalink to &quot;三、练后拉伸（5 分钟）&quot;">​</a></h3><h4 id="_3-1-股四头肌拉伸" tabindex="-1">3.1 股四头肌拉伸 <a class="header-anchor" href="#_3-1-股四头肌拉伸" aria-label="Permalink to &quot;3.1 股四头肌拉伸&quot;">​</a></h4><p><img src="'+A+'" alt="股四头肌拉伸"></p><ul><li>站姿或跪姿，将脚后跟拉向臀部</li><li><strong>膝盖不要外展</strong>（保持双膝并拢）</li><li><strong>每侧保持 30 秒 × 2 组</strong></li></ul><h4 id="_3-2-腘绳肌拉伸" tabindex="-1">3.2 腘绳肌拉伸 <a class="header-anchor" href="#_3-2-腘绳肌拉伸" aria-label="Permalink to &quot;3.2 腘绳肌拉伸&quot;">​</a></h4><p><img src="'+T+'" alt="腘绳肌拉伸"></p><ul><li>坐姿或站姿，单腿前伸脚尖朝上</li><li>身体前倾，感受大腿后侧拉伸</li><li><strong>每侧保持 30 秒 × 2 组，拉伸时不要弓背</strong></li></ul><h4 id="_3-3-臀大肌拉伸" tabindex="-1">3.3 臀大肌拉伸 <a class="header-anchor" href="#_3-3-臀大肌拉伸" aria-label="Permalink to &quot;3.3 臀大肌拉伸&quot;">​</a></h4><p><img src="'+F+'" alt="臀大肌拉伸"></p><ul><li>坐姿，一只脚踝搭在另一侧膝盖上</li><li>身体前倾，感受臀部外侧拉伸</li><li><strong>每侧保持 30 秒 × 2 组</strong></li></ul><h4 id="_3-4-梨状肌拉伸" tabindex="-1">3.4 梨状肌拉伸 <a class="header-anchor" href="#_3-4-梨状肌拉伸" aria-label="Permalink to &quot;3.4 梨状肌拉伸&quot;">​</a></h4><p><img src="'+L+'" alt="梨状肌拉伸"></p><ul><li>深层的臀部拉伸，对久坐族非常重要</li><li><strong>每侧保持 30 秒 × 2 组</strong></li></ul><h4 id="_3-5-小腿拉伸" tabindex="-1">3.5 小腿拉伸 <a class="header-anchor" href="#_3-5-小腿拉伸" aria-label="Permalink to &quot;3.5 小腿拉伸&quot;">​</a></h4><p><img src="'+O+'" alt="小腿拉伸"></p><ul><li>手扶墙，前后弓步，后腿伸直脚后跟着地</li><li><strong>每侧保持 30 秒 × 2 组</strong></li></ul><hr><h2 id="🔥-第四天-可选-体态矫正-弱项加强" tabindex="-1">🔥 第四天（可选）：体态矫正 + 弱项加强 <a class="header-anchor" href="#🔥-第四天-可选-体态矫正-弱项加强" aria-label="Permalink to &quot;🔥 第四天（可选）：体态矫正 + 弱项加强&quot;">​</a></h2><blockquote><p>在 4 练的循环走法中加入这一天。但如果觉得太累或时间不够，完全可以跳过，走 3 练循环一样有效。 重点是<strong>体态矫正 + 后链加强 + 核心 + 有氧</strong>。</p></blockquote><h3 id="训练内容-45-60-分钟" tabindex="-1">训练内容（45-60 分钟） <a class="header-anchor" href="#训练内容-45-60-分钟" aria-label="Permalink to &quot;训练内容（45-60 分钟）&quot;">​</a></h3><h4 id="_1-弹力带面拉-face-pull" tabindex="-1">1. 弹力带面拉（Face Pull） <a class="header-anchor" href="#_1-弹力带面拉-face-pull" aria-label="Permalink to &quot;1. 弹力带面拉（Face Pull）&quot;">​</a></h4><ul><li><strong>4 组 × 15 次</strong>（高容量矫正体态）</li><li>弹力带/绳索，拉向面部，外旋收尾</li></ul><h4 id="_2-肩外旋-external-rotation" tabindex="-1">2. 肩外旋（External Rotation） <a class="header-anchor" href="#_2-肩外旋-external-rotation" aria-label="Permalink to &quot;2. 肩外旋（External Rotation）&quot;">​</a></h4><p><img src="'+t+'" alt="肩外旋"></p><ul><li><strong>3 组 × 15 次/侧</strong></li></ul><h4 id="_3-反向飞鸟-reverse-fly" tabindex="-1">3. 反向飞鸟（Reverse Fly） <a class="header-anchor" href="#_3-反向飞鸟-reverse-fly" aria-label="Permalink to &quot;3. 反向飞鸟（Reverse Fly）&quot;">​</a></h4><p><img src="'+s+'" alt="哑铃反向飞鸟"></p><ul><li><strong>3 组 × 15 次</strong></li></ul><h4 id="_4-绳索划船-宽握-—-中背加强" tabindex="-1">4. 绳索划船（宽握）— 中背加强 <a class="header-anchor" href="#_4-绳索划船-宽握-—-中背加强" aria-label="Permalink to &quot;4. 绳索划船（宽握）— 中背加强&quot;">​</a></h4><p><img src="'+l+'" alt="坐姿绳索划船"></p><ul><li><strong>3 组 × 12-15 次</strong>（比拉日用更轻的重量，专注收缩感）</li></ul><h4 id="_5-核心训练-选-2-个-交替做" tabindex="-1">5. 核心训练（选 2 个，交替做） <a class="header-anchor" href="#_5-核心训练-选-2-个-交替做" aria-label="Permalink to &quot;5. 核心训练（选 2 个，交替做）&quot;">​</a></h4><ul><li>悬垂抬腿/跪姿卷腹：3 组 × 10-15 次</li><li>平板支撑：3 组 × 30-60 秒</li><li>死虫式（Dead Bug）：3 组 × 10 次/侧</li></ul><h4 id="_6-有氧-15-20-分钟" tabindex="-1">6. 有氧（15-20 分钟） <a class="header-anchor" href="#_6-有氧-15-20-分钟" aria-label="Permalink to &quot;6. 有氧（15-20 分钟）&quot;">​</a></h4><ul><li>跑步机快走（坡度 10-12，速度 4-5km/h）</li><li>或椭圆机</li><li>心率控制在 120-140bpm（低强度稳态有氧）</li></ul><h3 id="练后拉伸" tabindex="-1">练后拉伸 <a class="header-anchor" href="#练后拉伸" aria-label="Permalink to &quot;练后拉伸&quot;">​</a></h3><p>参照前三天灵活组合，重点是<strong>胸部 + 髋屈肌</strong>（久坐最紧张的两个区域）。</p><hr><h2 id="🛡️-肩膀保护专项指南" tabindex="-1">🛡️ 肩膀保护专项指南 <a class="header-anchor" href="#🛡️-肩膀保护专项指南" aria-label="Permalink to &quot;🛡️ 肩膀保护专项指南&quot;">​</a></h2><blockquote><p>因为你提到「有点肩膀疼」，以下是整个训练周期中必须遵守的肩部保护策略：</p></blockquote><table tabindex="0"><thead><tr><th>规则</th><th>说明</th></tr></thead><tbody><tr><td><strong>每天做面拉 + 肩外旋</strong></td><td>两个动作是肩关节的「保险」，越多越好</td></tr><tr><td><strong>推类动作手肘不要超过身体平面</strong></td><td>卧推/推胸时，杠铃下放太深会让肩关节前侧承受巨大压力</td></tr><tr><td><strong>推肩时不要完全锁死肘关节</strong></td><td>锁死 = 压力从肌肉转移到关节</td></tr><tr><td><strong>肩疼立即停止</strong></td><td>不要「忍着练」，找出原因再调整</td></tr><tr><td><strong>弹力带热身比你想的重要</strong></td><td>肩袖肌群血流量低，不充分热身容易受伤</td></tr><tr><td><strong>加强中下斜方肌</strong></td><td>面拉、反向飞鸟、划船——拉&gt;推</td></tr></tbody></table><hr><h2 id="📈-动作替换表" tabindex="-1">📈 动作替换表 <a class="header-anchor" href="#📈-动作替换表" aria-label="Permalink to &quot;📈 动作替换表&quot;">​</a></h2><blockquote><p>如果身体不适或器材被占，可以用以下等价动作替换：</p></blockquote><table tabindex="0"><thead><tr><th>原始动作</th><th>替换动作 A</th><th>替换动作 B</th></tr></thead><tbody><tr><td>高位下拉</td><td>引体向上（辅助/自重）</td><td>器械高位下拉（不同握把）</td></tr><tr><td>坐姿绳索划船</td><td>器械划船</td><td>哑铃单臂划船</td></tr><tr><td>器械推胸</td><td>哑铃卧推（注意肩膀）</td><td>绳索夹胸</td></tr><tr><td>器械推肩</td><td>哑铃推肩（轻重量）</td><td>器械侧平举</td></tr><tr><td>史密斯深蹲</td><td>哑铃高脚杯深蹲</td><td>器械哈克深蹲</td></tr><tr><td>腿举</td><td>哑铃弓步走</td><td>保加利亚分腿蹲</td></tr></tbody></table><hr><h2 id="🍽️-饮食配合提示" tabindex="-1">🍽️ 饮食配合提示 <a class="header-anchor" href="#🍽️-饮食配合提示" aria-label="Permalink to &quot;🍽️ 饮食配合提示&quot;">​</a></h2><blockquote><p>详细的饮食计划见 <a href="./diet.html">饮食计划</a></p></blockquote><ul><li><strong>训练前（30-60 分钟）</strong>：快碳 + 少量蛋白质（如：全麦吐司 1 片 + 香蕉半根）</li><li><strong>训练后（30 分钟内）</strong>：蛋白质 + 快碳（如：蛋白粉 1 勺 + 香蕉 1 根）</li><li><strong>补剂</strong>：一水肌酸每日 3-5g，坚持服用（不需要停用期）</li><li><strong>每日饮水量</strong>：目前 1500ml 偏少，建议提升到 <strong>2000-2500ml</strong></li></ul><hr><h2 id="📊-进度追踪" tabindex="-1">📊 进度追踪 <a class="header-anchor" href="#📊-进度追踪" aria-label="Permalink to &quot;📊 进度追踪&quot;">​</a></h2><blockquote><p>建议每走完 3-4 个循环后回顾一次，每 2-3 个月拍照对比。</p></blockquote><table tabindex="0"><thead><tr><th>维度</th><th>记录方式</th></tr></thead><tbody><tr><td><strong>体重</strong></td><td>每天早上空腹测量，每周取平均值</td></tr><tr><td><strong>力量进步</strong></td><td>每次记录主项重量 × 次数，走完一轮循环后比较是否进步</td></tr><tr><td><strong>体态变化</strong></td><td>侧面拍照，观察圆肩程度、头前伸角度</td></tr><tr><td><strong>肩部感受</strong></td><td>训练日志中写一句：训练后肩膀是否不适（0-10 分）</td></tr><tr><td><strong>循环追踪</strong></td><td>简单记「今天第X天」，下次来就知道该练什么了</td></tr></tbody></table><hr><blockquote><p>📅 <strong>计划制定日期</strong>：2026-07-08 🔄 <strong>下次更新时间</strong>：4 周后（2026-08-05）或身体有明显变化时 💬 <strong>训练日志记录</strong>：建议用手机备忘录或 Notion，记两件事：<strong>① 今天第几天 ② 主项重量/次数</strong></p></blockquote>',288)])])}const Y=n(V,[["render",M]]);export{Q as __pageData,Y as default};
